    overlay.style.width = "100vw"; overlay.style.height = "100vh";
    overlay.style.background = "linear-gradient(135deg, #0f172a 0%, #1e293b 100%)";
    overlay.style.zIndex = "10000"; overlay.style.display = "flex"; overlay.style.flexDirection = "column"; overlay.style.fontFamily = "Inter, sans-serif";

    var gisSubs = [];
    function cleanupGIS() { gisSubs.forEach(function (id) { try { webMI.data.unsubscribe(id); } catch (e) { } }); gisSubs = []; }

    var head = U.x(doc, "div"); head.style.padding = "15px 30px"; head.style.display = "flex"; head.style.justifyContent = "space-between"; head.style.alignItems = "center"; head.style.background = "rgba(15, 23, 42, 0.9)"; head.style.borderBottom = "1px solid rgba(255,255,255,0.1)";
    var leftSide = U.x(doc, "div"); leftSide.style.display = "flex"; leftSide.style.alignItems = "center"; leftSide.style.gap = "20px";
    var title = U.x(doc, "h2"); title.style.margin = "0"; title.style.color = "#fff"; title.style.fontSize = "20px"; title.textContent = "Centro de Control Topográfico"; leftSide.appendChild(title);
    var tabs = U.x(doc, "div"); tabs.style.display = "flex"; tabs.style.background = "#0f172a"; tabs.style.padding = "4px"; tabs.style.borderRadius = "8px"; tabs.style.border = "1px solid #334155";
    function createTab(label, active, click) {
        var t = U.x(doc, "div"); t.textContent = label; t.style.padding = "6px 16px"; t.style.borderRadius = "6px"; t.style.cursor = "pointer"; t.style.fontSize = "13px"; t.style.fontWeight = "600";
        if (active) { t.style.background = "#3b82f6"; t.style.color = "#fff"; } else { t.style.color = "#94a3b8"; }
        t.onclick = function () { click(t); }; return t;
    }
    var contentArea = U.x(doc, "div"); contentArea.style.flex = "1"; contentArea.style.position = "relative";
    var tabL = createTab("Esquema Lógico", true, function (me) { cleanupGIS(); me.style.background = "#3b82f6"; me.style.color = "#fff"; tabM.style.background = "transparent"; tabM.style.color = "#94a3b8"; renderLogic(); });
    var tabM = createTab("Mapa Geográfico", false, function (me) { me.style.background = "#3b82f6"; me.style.color = "#fff"; tabL.style.background = "transparent"; tabL.style.color = "#94a3b8"; renderMap(); });
    tabs.appendChild(tabL); tabs.appendChild(tabM); leftSide.appendChild(tabs); head.appendChild(leftSide);
    var closeBtn = U.x(doc, "button"); closeBtn.innerHTML = "&times;"; closeBtn.style.background = "rgba(255,255,255,0.1)"; closeBtn.style.border = "none"; closeBtn.style.color = "#fff"; closeBtn.style.fontSize = "24px"; closeBtn.style.width = "36px"; closeBtn.style.height = "36px"; closeBtn.style.borderRadius = "50%"; closeBtn.style.cursor = "pointer"; closeBtn.onclick = function () { cleanupGIS(); doc.body.removeChild(overlay); }; head.appendChild(closeBtn);
    overlay.appendChild(head); overlay.appendChild(contentArea); doc.body.appendChild(overlay);

    function renderLogic() {
        contentArea.innerHTML = ""; var vp = U.x(doc, "div");
        vp.style.width = "100%"; vp.style.height = "100%";
        vp.style.overflow = "auto"; vp.style.padding = "40px";
        vp.style.position = "relative"; // Fix: Required for absolute child scroll capture
        contentArea.appendChild(vp);
        HeaderTopo.render(vp, { fullscreen: true, onNodeClick: function (node, el) { HeaderTopo.selection = { node: node, el: el }; el.style.boxShadow = "0 0 0 4px #3b82f6"; } });
    }

    function renderMap() {
        contentArea.innerHTML = ""; if (!doc.getElementById("leaflet-css")) { var l = doc.createElement("link"); l.rel = "stylesheet"; l.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"; doc.head.appendChild(l); }
        var win = doc.defaultView || window; if (!win.L) { var s = doc.createElement("script"); s.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"; s.onload = function () { initMap(win.L); }; doc.head.appendChild(s); } else { initMap(win.L); }
        function initMap(L) {
            var mDiv = U.x(doc, "div"); mDiv.style.width = "100%"; mDiv.style.height = "100%"; contentArea.appendChild(mDiv);
            var map = L.map(mDiv).setView([21.1619, -86.8515], 13);
            var dark = L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', { attribution: '&copy; CARTO' }).addTo(map);
            var satellite = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: '&copy; Esri' });
            var voyager = L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', { attribution: '&copy; CARTO' });
            L.control.layers({ "Oscuro": dark, "Satelital": satellite, "Voyager": voyager }, null, { collapsed: false }).addTo(map);

            var markers = {}, pipes = [];
            var iconT = L.divIcon({ html: "<div style='background:#2563eb; width:12px; height:12px; border:2px solid #fff; border-radius:50%; box-shadow:0 0 10px rgba(37,99,235,0.8);'></div>", iconSize: [16, 16], iconAnchor: [8, 8] });
            var iconC = L.divIcon({ html: "<div style='background:#059669; width:12px; height:12px; border:2px solid #fff; border-radius:3px; box-shadow:0 0 10px rgba(5,150,105,0.8);'></div>", iconSize: [16, 16], iconAnchor: [8, 8] });

            function refresh() {
                cleanupGIS();
                HeaderTopo.fetchConfig(base + ".topoNode", function (cfg) {
                    var addrs = cfg.nodes.map(function (n) { return n.base + ".topoCoords"; });
                    webMI.data.read(addrs, function (results) {
                        var coords = {}, bounds = [];
                        cfg.nodes.forEach(function (node, idx) {
                            var val = (results[idx] && (typeof results[idx].value !== 'undefined' ? results[idx].value : results[idx]));
                            if (val && typeof val === "string" && val.indexOf(",") > 0) {
                                var pts = val.split(","), lat = parseFloat(pts[0]), lon = parseFloat(pts[1]);
                                coords[node.id] = { lat: lat, lon: lon }; bounds.push([lat, lon]);
                                (function (n, lat, lon) {
                                    U.discoverEquipment(n.base, function (data) {
                                        var isAP = n.base.indexOf("Potables") >= 0 || n.base.indexOf("Circuito") >= 0;
                                        var isCurrent = (n.base === base);
                                        var mIconHTML = isAP ?
                                            "<div style='background:#2563eb; width:12px; height:12px; border:2px solid #fff; border-radius:50%; box-shadow:0 0 10px rgba(0,0,0,0.3);'></div>" :
                                            "<div style='background:#059669; width:12px; height:12px; border:2px solid #fff; border-radius:3px; box-shadow:0 0 10px rgba(0,0,0,0.3);'></div>";

                                        if (isCurrent) {
                                            mIconHTML = "<div class='topo-pulse' style='background:#facc15; width:16px; height:16px; border:3px solid #fff; border-radius:50%;'></div>";
                                        }

                                        var mIcon = L.divIcon({ className: isCurrent ? 'pulse-marker' : '', html: mIconHTML, iconSize: [isCurrent ? 24 : 16, isCurrent ? 24 : 16], iconAnchor: [isCurrent ? 12 : 8, isCurrent ? 12 : 8] });
                                        if (markers[n.id]) map.removeLayer(markers[n.id]);
                                        var m = L.marker([lat, lon], { icon: mIcon }).addTo(map); markers[n.id] = m;

                                        if (isCurrent) {
                                            map.flyTo([lat, lon], 17, { animate: true, duration: 1.5 });
                                        }
                                        var live = { level: "--", percent: "0", meters: [] };

                                        // Refined Naming
                                        var typeLabel = isAP ? "Tanque" : "Cárcamo";
                                        var cleanID = n.id.replace(/_/g, " ").replace(/Carcamo|Tanque/gi, "").trim();
                                        var displayName = typeLabel + " " + cleanID;

                                        function buildH() {
                                            var h = "<div style='min-width:180px; font-family:Inter, sans-serif;'><b style='color:#1e40af;'>" + displayName + "</b><br/>";
                                            h += "<div style='margin-top:5px; padding:5px; background:#f8fafc; border-radius:4px;'>";
                                            h += "<div style='font-size:10px; color:#64748b; font-weight:bold;'>NIVEL</div>";
                                            h += "<div style='display:flex; justify-content:space-between; align-items:baseline;'><b>" + live.level + " m</b> <span style='color:#3b82f6; font-size:11px;'>" + live.percent + "%</span></div>";
                                            h += "</div>";
                                            if (data.meters.length > 0) {
                                                h += "<div style='margin-top:5px; border-top:1px solid #e2e8f0; padding-top:5px;'>";
                                                data.meters.forEach(function (met, mi) {
                                                    var d = live.meters[mi] || { f: "--", p: "--" };
                                                    var mName = (met.name || "M").replace(/Caudalimetro_/g, "");
                                                    h += "<div style='display:flex; justify-content:space-between; font-size:11px; margin-bottom:2px;'>";
                                                    h += "<span style='color:#64748b'>" + mName + ":</span>";
                                                    h += "<span><b>" + d.f + "</b> <small>l/s</small> | <b>" + d.p + "</b> <small>kg</small></span>";
                                                    h += "</div>";
                                                });
                                                h += "</div>";
                                            }
                                            h += "</div>"; return h;
                                        }
                                        function up() { m.bindPopup(buildH()); }
                                        U.addSub(n.base + ".level", function (r) { live.level = parseFloat(r.value || 0).toFixed(2); up(); }, gisSubs);
                                        U.addSub(n.base + ".level_percent", function (r) { live.percent = Math.round(r.value || 0); up(); }, gisSubs);
                                        data.meters.forEach(function (met, mi) {
                                            var p = String(met.address || ""); if (p.indexOf("s=") >= 0) p = p.slice(p.indexOf("s=") + 2);
                                            live.meters[mi] = { f: "--", p: "--" };
                                            U.addSub(p + ".current_flow", function (r) { live.meters[mi].f = parseFloat(r.value || 0).toFixed(1); up(); }, gisSubs);
                                            U.addSub(p + ".current_pressure", function (r) { live.meters[mi].p = parseFloat(r.value || 0).toFixed(2); up(); }, gisSubs);
                                        });
                                    });
                                })(node, lat, lon);
                            }
                        });
                        if (bounds.length > 0) map.fitBounds(bounds, { padding: [50, 50] });
                        pipes.forEach(function (p) { map.removeLayer(p); }); pipes = [];
                        (cfg.connections || []).forEach(function (e) {
                            var c1 = coords[e.from], c2 = coords[e.to];
                            if (c1 && c2) pipes.push(L.polyline([[c1.lat, c1.lon], [c2.lat, c2.lon]], { color: '#3b82f6', weight: 3, opacity: 0.5, dashArray: '5, 10' }).addTo(map));
                        });
                    });
                });
            }
            refresh();
            var sBar = U.x(doc, "div"); sBar.style.position = "absolute"; sBar.style.top = "10px"; sBar.style.left = "55px"; sBar.style.zIndex = "1100"; sBar.style.display = "flex";
            var sIn = U.x(doc, "input"); sIn.placeholder = "Buscar..."; sIn.style.padding = "8px"; sIn.style.borderRadius = "4px 0 0 4px"; sIn.style.border = "1px solid #334155"; sIn.style.background = "#1e293b"; sIn.style.color = "#fff";
            var sBtn = U.x(doc, "button"); sBtn.innerHTML = "🔍"; sBtn.style.padding = "8px"; sBtn.style.background = "#3b82f6"; sBtn.style.color = "#fff"; sBtn.style.border = "none"; sBtn.style.borderRadius = "0 4px 4px 0"; sBar.appendChild(sIn); sBar.appendChild(sBtn); contentArea.appendChild(sBar);
            sBtn.onclick = function () {
                var q = sIn.value; if (!q) return;
                var coordMatch = q.match(/^([-+]?\d+\.\d+),\s*([-+]?\d+\.\d+)$/);
                if (coordMatch) { map.setView([parseFloat(coordMatch[1]), parseFloat(coordMatch[2])], 17); }
                else { fetch("https://nominatim.openstreetmap.org/search?format=json&q=" + encodeURIComponent(q)).then(function (r) { return r.json(); }).then(function (d) { if (d && d[0]) map.setView([d[0].lat, d[0].lon], 16); }); }
            };
            map.on('click', function (e) {
                if (HeaderTopo.selection) {
                    webMI.data.write(HeaderTopo.selection.node.base + ".topoCoords", e.latlng.lat + ", " + e.latlng.lng);
                    setTimeout(function () { refresh(); }, 500); HeaderTopo.selection = null;
                }
            });
        }
    }
    renderLogic();
};
